cpp.setup:
auto* control = new fluent::scrolling::ImageViewer(%PARENT%);
QImage img(220, 128, QImage::Format_ARGB32);
img.fill(QColor(QStringLiteral("#1e3a5f")));
QPainter p(&img);
p.setPen(Qt::NoPen);
p.setBrush(QColor(QStringLiteral("#38bdf8")));
p.drawRoundedRect(24, 24, 84, 80, 12, 12);
p.setBrush(QColor(QStringLiteral("#f59e0b")));
p.drawEllipse(128, 30, 68, 68);
p.end();
control->setPixmap(QPixmap::fromImage(img));
